def strategy(history, rng):
    n = len(history)
    if n >= 99:
        return 'D'
    if n == 0:
        return 'C'

    my_last = history[-1][0]
    opp_last = history[-1][1]
    my_prev = history[-2][0] if n >= 2 else my_last

    total_opp_d = 0
    total_my_d = 0
    opp_d_recent = 0
    my_d_recent = 0
    start = n - 8
    if start < 0:
        start = 0

    for i in range(n):
        a = history[i][0]
        b = history[i][1]
        if a == 'D':
            total_my_d += 1
            if i >= start:
                my_d_recent += 1
        if b == 'D':
            total_opp_d += 1
            if i >= start:
                opp_d_recent += 1

    opp_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_streak += 1
        else:
            break

    tolerated = 0
    punished = 0
    lo = n - 30
    if lo < 0:
        lo = 0
    for i in range(lo, n - 1):
        if history[i][0] == 'D' and history[i][1] == 'C':
            nxt = history[i + 1][1]
            if nxt == 'C':
                tolerated += 1
            elif nxt == 'D':
                punished += 1

    coop_limit = 2 + n // 8
    exploit = (
        tolerated > 0 and
        punished == 0 and
        opp_d_recent <= 1 and
        total_opp_d <= coop_limit
    )

    if (
        opp_streak >= 3 or
        opp_d_recent >= 4 or
        (total_opp_d >= 5 and total_opp_d * 2 >= n and opp_d_recent >= 2)
    ):
        return 'D'

    if n == 98:
        if exploit:
            return 'D'
        if opp_last == 'D' or opp_streak >= 2 or opp_d_recent >= 2:
            return 'D'
        return 'C'

    if opp_last == 'D':
        if my_prev == 'D' and opp_streak <= 2:
            return 'C'
        return 'D'

    if my_last == 'D':
        return 'C'

    if exploit:
        if my_prev == 'D' or total_opp_d == 0:
            return 'D'

    if (
        total_my_d == 0 and
        opp_d_recent == 0 and
        total_opp_d <= coop_limit and
        8 <= n <= 90
    ):
        return 'D'

    return 'C'
